with accounts_by_customer as (select customer_id, avg(balance) as avg_balance, sum(case when account_type = 'SAVINGS' then 1 else 0 end) as savings_count from accounts where month(opened_date) in (3, 5, 9) group by customer_id) select c.id, c.is_active, abc.avg_balance, abc.savings_count from customers c inner join accounts_by_customer abc on c.id = abc.customer_id order by avg_balance
